public class Solution {
    // O(1): potência de dois tem exatamente um bit 1; x & (x - 1) apaga esse bit.
    static boolean ehPotenciaDeDois(long x) {
        return x > 0 && (x & (x - 1)) == 0;
    }

    // O(n): i tem os bits de i/2 mais o bit mais baixo.
    static int[] contarBits(int n) {
        if (n < 0) throw new IllegalArgumentException("n negativo");
        int[] bits = new int[n + 1];
        for (int i = 1; i <= n; i++) bits[i] = bits[i >> 1] + (i & 1);
        return bits;
    }

    // O(n) tempo, O(1) memória: o XOR total é a ^ b; um bit ligado nele separa os dois.
    static int[] doisUnicos(int[] nums) {
        int xorTotal = 0;
        for (int x : nums) xorTotal ^= x;
        int separador = xorTotal & -xorTotal;
        int a = 0;
        for (int x : nums) if ((x & separador) != 0) a ^= x;
        int b = xorTotal ^ a;
        return a < b ? new int[] {a, b} : new int[] {b, a};
    }

    // O(32 n) tempo, O(1) memória: o resto por 3 da soma de cada bit é o bit do único.
    static int unicoEntreTriplos(int[] nums) {
        int resultado = 0;
        for (int bit = 0; bit < 32; bit++) {
            int soma = 0;
            for (int x : nums) soma += (x >>> bit) & 1;
            if (soma % 3 != 0) resultado |= 1 << bit;
        }
        return resultado;
    }
}

