import org.junit.jupiter.api.Test;
import static org.junit.jupiter.api.Assertions.*;

class SolutionTest {
    @Test void potenciasDeDois() {
        assertTrue(Solution.ehPotenciaDeDois(1));
        assertTrue(Solution.ehPotenciaDeDois(64));
        assertTrue(Solution.ehPotenciaDeDois(1L << 62));
        assertFalse(Solution.ehPotenciaDeDois(0));
        assertFalse(Solution.ehPotenciaDeDois(-8));
        assertFalse(Solution.ehPotenciaDeDois(96));
        assertFalse(Solution.ehPotenciaDeDois(Long.MIN_VALUE));
    }

    @Test void contagemDeBits() {
        assertArrayEquals(new int[] {0}, Solution.contarBits(0));
        assertArrayEquals(new int[] {0, 1, 1, 2, 1, 2}, Solution.contarBits(5));
        int[] grande = Solution.contarBits(100_000);
        for (int i = 0; i <= 100_000; i += 997) assertEquals(Integer.bitCount(i), grande[i]);
        assertThrows(IllegalArgumentException.class, () -> Solution.contarBits(-1));
    }

    @Test void doisUnicosOrdenados() {
        assertArrayEquals(new int[] {3, 5}, Solution.doisUnicos(new int[] {1, 2, 1, 3, 2, 5}));
        assertArrayEquals(new int[] {-7, 0}, Solution.doisUnicos(new int[] {0, -7}));
        assertArrayEquals(new int[] {Integer.MIN_VALUE, Integer.MAX_VALUE},
            Solution.doisUnicos(new int[] {Integer.MAX_VALUE, 4, Integer.MIN_VALUE, 4}));
    }

    @Test void unicoEntreTriplos() {
        assertEquals(7, Solution.unicoEntreTriplos(new int[] {-2, -2, 7, -2}));
        assertEquals(-4, Solution.unicoEntreTriplos(new int[] {5, -4, 5, 5}));
        assertEquals(99, Solution.unicoEntreTriplos(new int[] {0, 1, 0, 1, 0, 1, 99}));
        assertEquals(Integer.MIN_VALUE, Solution.unicoEntreTriplos(new int[] {3, 3, Integer.MIN_VALUE, 3}));
    }
}
